import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, Building2, CalendarDays, ChevronDown, CircleDollarSign, Clock3, FileSpreadsheet, LayoutDashboard, Menu, Plus, Search, Settings, Users, Wallet, X, Moon, UserRound, CheckCircle2, ClipboardList, Link2, Copy, MapPin, RefreshCw, Trash2, MessageCircle, Send } from 'lucide-react';
import './style.css';

const api = async (url, options={}) => {
  const res = await fetch('/api'+url, { credentials: 'same-origin', headers: { 'Content-Type':'application/json' }, ...options });
  const data = await res.json().catch(()=>({}));
  if (!res.ok) throw new Error(data.error || 'Ошибка запроса');
  return data;
};
const money = n => new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(Number(n||0));
const dateText = d => d ? new Date(d).toLocaleDateString('ru-RU') : '—';
const dateTimeText = d => d ? new Date(d).toLocaleString('ru-RU', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' }) : '—';

function App({onLogout}) {
  const [page,setPage]=useState('overview'), [mobileOpen,setMobileOpen]=useState(false);
  const [summary,setSummary]=useState({employees:0,branches:0,tasks:0,completedTasks:0});
  const [employees,setEmployees]=useState([]), [branches,setBranches]=useState([]), [tasks,setTasks]=useState([]), [applications,setApplications]=useState([]), [invites,setInvites]=useState([]), [locationSelections,setLocationSelections]=useState([]), [reports,setReports]=useState([]), [reportComments,setReportComments]=useState({});
  const [query,setQuery]=useState(''), [modal,setModal]=useState(''), [error,setError]=useState(''), [busy,setBusy]=useState(false), [refreshing,setRefreshing]=useState(false), [inviteUrl,setInviteUrl]=useState(''), [mapSelection,setMapSelection]=useState(null);
  const [branchName,setBranchName]=useState(''), [branchCity,setBranchCity]=useState(''), [branchCityEdits,setBranchCityEdits]=useState({});
  const [inviteForm,setInviteForm]=useState({branchId:'',daysValid:'30'});
  const [taskForm,setTaskForm]=useState({employeeId:'',title:'',description:'',dueDate:''});
  const load=async()=>{try{const [sm,e,b,t,a,i,ls,rp]=await Promise.all([api('/summary'),api('/employees'),api('/branches'),api('/tasks'),api('/applications'),api('/invites'),api('/location-selections'),api('/reports')]);setSummary(sm);setEmployees(e);setBranches(b);setBranchCityEdits(old=>({...Object.fromEntries(b.map(x=>[x.id,x.city||''])),...old}));setTasks(t);setApplications(a);setInvites(i);setLocationSelections(ls);setReports(rp);return true;}catch(e){setError(e.message);return false;}};
  const refreshData=async()=>{setRefreshing(true);setError('');try{await load();}finally{setRefreshing(false);}};
  useEffect(()=>{load();const timer=setInterval(load,300000);return()=>clearInterval(timer);},[]);
  useEffect(()=>{if(!mapSelection||!window.L||!document.getElementById('admin-location-map'))return;const loc=mapSelection.location;const map=window.L.map('admin-location-map').setView([loc.latitude,loc.longitude],14);window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const marker=window.L.marker([loc.latitude,loc.longitude]).addTo(map);marker.bindPopup(`<b>${safeMap(loc.district||loc.city||'Объект')}</b><br>${safeMap(loc.city)}, ${safeMap(loc.region)}`).openPopup();return()=>map.remove();},[mapSelection]);
  const run=async fn=>{setBusy(true);setError('');try{await fn();await load();setModal('');}catch(e){setError(e.message);}finally{setBusy(false);}};
  const removeRecord=(url,label)=>{if(!window.confirm(`Удалить «${label}»? Это действие нельзя отменить.`))return;run(()=>api(url,{method:'DELETE'}));};
  const filtered=useMemo(()=>employees.filter(e=>`${e.fullName} ${e.position||''} ${e.branch?.name||''}`.toLowerCase().includes(query.toLowerCase())),[employees,query]);
  const nav=[['overview','Обзор',LayoutDashboard],['tasks','Задания',ClipboardList],['employees','Сотрудники',Users],['applications','Анкеты',FileSpreadsheet],['invites','Приглашения',Link2],['branches','Филиалы',Building2],['location-requests','Выбор объектов',MapPin],['reports','Отчёты',FileSpreadsheet]];
  const title=nav.find(n=>n[0]===page)?.[1]||'Обзор';
  const createInvite=async()=>{setBusy(true);setError('');try{const r=await api('/invites',{method:'POST',body:JSON.stringify(inviteForm)});setInviteUrl(r.url);await load();setModal('inviteResult');}catch(e){setError(e.message);}finally{setBusy(false);}};
  const reviewApplication=async(id,status)=>{setBusy(true);setError('');try{const r=await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({status})});await load();if(r.activationUrl){setInviteUrl(r.activationUrl);setModal('activationResult');}}catch(e){setError(e.message);}finally{setBusy(false);}};
  const createTask=()=>run(async()=>api('/tasks',{method:'POST',body:JSON.stringify(taskForm)}));
  const reviewLocation=(id,status)=>run(async()=>api(`/location-selections/${id}`,{method:'PATCH',body:JSON.stringify({status})}));
  const setTaskStatus=(task,status)=>run(async()=>api(`/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({status})}));
  const reviewReport=(report,status)=>run(async()=>api(`/reports/${report.id}`,{method:'PATCH',body:JSON.stringify({status,adminComment:reportComments[report.id]||''})}));
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen?'open':''}`}>
      <div className="brand"><img className="brand-logo" src="/parkwright-logo.png" alt="ПаркРайт"/><button className="mobile-close" onClick={()=>setMobileOpen(false)}><X/></button></div>
      <div className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div>
      <nav>{nav.map(([id,label,Icon])=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>{setPage(id);setMobileOpen(false);}}><Icon size={18}/><span>{label}</span>{id==='employees'&&<em>{employees.length}</em>}{id==='tasks'&&<em>{tasks.filter(t=>t.status!=='Выполнено').length}</em>}{id==='applications'&&<em>{applications.length}</em>}{id==='location-requests'&&<em>{locationSelections.filter(x=>x.status==='На проверке').length}</em>}{id==='reports'&&<em>{reports.filter(x=>x.status==='На проверке').length}</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="workspace"><div className="workspace-icon"><Building2 size={17}/></div><div><b>Предприятие</b><small>Все филиалы</small></div><ChevronDown size={15}/></div><div className="profile-mini"><div className="avatar">РУ</div><div><b>Руководитель</b><small>Главный руководитель</small></div><Settings size={17}/></div></div>
    </aside>
    {mobileOpen&&<div className="scrim" onClick={()=>setMobileOpen(false)}/>}
    <main className="main-area">
      <header className="topbar"><button className="menu-btn" onClick={()=>setMobileOpen(true)}><Menu/></button><div className="breadcrumbs">Рабочее пространство <span>/</span> <b>{title}</b></div><div className="top-actions"><div className="status-dot"><i/>Система активна</div><button className="icon-btn" title="Тёмная тема"><Moon size={18}/></button><button className="logout-btn" onClick={onLogout}>Выйти</button></div></header>
      <div className="content">
        <div className="page-heading"><div><div className="eyebrow">ПАНЕЛЬ УПРАВЛЕНИЯ</div><h1>{page==='overview'?'Добро пожаловать':title}</h1><p>{page==='overview'?'Управляйте сотрудниками и контролируйте выполнение заданий.':'Управляйте данными и рабочими заданиями предприятия.'}</p></div><div className="heading-actions"><button className="secondary-btn refresh-btn" onClick={refreshData} disabled={refreshing}><RefreshCw size={16} className={refreshing?'spin':''}/>{refreshing?'Обновление...':'Обновить данные'}</button>{page==='tasks'&&<button className="primary-btn" onClick={()=>{setTaskForm({employeeId:employees[0]?.id||'',title:'',description:'',dueDate:''});setModal('task')}}><Plus size={17}/> Создать задание</button>}{page==='employees'&&<button className="primary-btn" onClick={()=>{setInviteForm({branchId:branches[0]?.id||'',daysValid:'30'});setModal('invite')}}><Link2 size={17}/> Пригласить сотрудников</button>}</div></div>
        {error&&<div className="alert"><span>{error}</span><button onClick={()=>setError('')}><X size={16}/></button></div>}
        {page==='overview'&&<><div className="stats-grid"><Stat icon={Users} label="Действующие сотрудники" value={summary.employees} note="По всем филиалам" tone="violet"/><Stat icon={Building2} label="Филиалы" value={summary.branches} note="Активные объекты" tone="blue"/><Stat icon={ClipboardList} label="Всего заданий" value={summary.tasks} note="Назначено сотрудникам" tone="green"/><Stat icon={CheckCircle2} label="Выполнено" value={summary.completedTasks} note="Заданий закрыто" tone="amber"/></div>
          <section className="panel"><div className="panel-head"><div><h2>Последние задания</h2><p>Текущие поручения сотрудникам</p></div><button className="text-btn" onClick={()=>setPage('tasks')}>Все задания →</button></div><TaskTable tasks={tasks.slice(0,6)} onStatus={setTaskStatus} onDelete={t=>removeRecord(`/tasks/${t.id}`,t.title)}/>{!tasks.length&&<div className="empty">Заданий пока нет. Создайте первое поручение сотруднику.</div>}</section>
          <section className="panel note-panel"><div className="note-icon"><CheckCircle2/></div><div><b>Работа через задания</b><p>Создавайте поручения, назначайте ответственного сотрудника и срок. Сотрудник увидит задание в личном кабинете и сможет сообщить о выполнении.</p></div></section></>}
        {page==='tasks'&&<section className="panel"><div className="panel-head"><div><h2>Задания сотрудников</h2><p>Назначайте поручения и отслеживайте их выполнение</p></div><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск задания или сотрудника..."/></div></div><TaskTable tasks={tasks.filter(t=>`${t.title} ${t.employee?.fullName||''}`.toLowerCase().includes(query.toLowerCase()))} onStatus={setTaskStatus} onDelete={t=>removeRecord(`/tasks/${t.id}`,t.title)}/>{!tasks.length&&<div className="empty">Заданий пока нет. Нажмите «Создать задание».</div>}</section>}
        {page==='employees'&&<section className="panel"><div className="panel-head"><div><h2>База сотрудников</h2><p>Карточки сотрудников предприятия</p></div><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск сотрудника..."/></div></div><div className="table-wrap"><table><thead><tr><th>СОТРУДНИК</th><th>ДОЛЖНОСТЬ</th><th>ФИЛИАЛ</th><th>СТАТУС</th><th>ЗАДАНИЯ</th><th></th></tr></thead><tbody>{filtered.map(e=><tr key={e.id}><td><div className="person-cell"><div className="avatar small">{e.fullName.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}</div><div><b>{e.fullName}</b><small>{e.phone||'Телефон не указан'}</small></div></div></td><td>{e.position||'—'}</td><td>{e.branch?.name||'—'}</td><td><span className={`pill ${e.status==='Работает'?'success':'muted'}`}>{e.status}</span></td><td>{tasks.filter(t=>t.employeeId===e.id&&t.status!=='Выполнено').length} активных</td><td><button className="icon-btn delete-icon" title="Удалить сотрудника" disabled={busy} onClick={()=>removeRecord(`/employees/${e.id}`,e.fullName)}><Trash2 size={16}/></button></td></tr>)}</tbody></table>{!filtered.length&&<div className="empty">Сотрудники не найдены</div>}</div></section>}
        {page==='applications'&&<section className="panel"><div className="panel-head"><div><h2>Заявки сотрудников</h2><p>Проверяйте анкеты перед созданием личного кабинета · Всего: {applications.length}</p></div></div><div className="table-wrap"><table><thead><tr><th>ФИО / ТЕЛЕФОН</th><th>ГОД РОЖДЕНИЯ / TELEGRAM</th><th>ФИЛИАЛ</th><th>СТАТУС</th><th>ДЕЙСТВИЕ</th></tr></thead><tbody>{applications.map(a=><tr key={a.id}><td><b>{a.fullName}</b><small className="subline">{a.phone}</small></td><td>{a.birthYear||'—'}<small className="subline">{a.telegramUsername ? `@${a.telegramUsername}` : 'Telegram не указан'}</small></td><td>{a.branch?.name||'—'}</td><td><span className={`pill ${a.status==='На проверке'?'warning':a.status==='Одобрена'?'success':'muted'}`}>{a.status}</span></td><td><div className="inline-actions action-cell-controls">{a.status==='На проверке'?<><button className="small-btn" onClick={()=>reviewApplication(a.id,'Одобрена')}>Одобрить</button><button className="small-btn danger-btn" onClick={()=>reviewApplication(a.id,'Отклонена')}>Отклонить</button></>:<span>{a.status}</span>}<button className="icon-btn delete-icon" title="Удалить анкету" disabled={busy} onClick={()=>removeRecord(`/applications/${a.id}`,a.fullName)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table>{!applications.length&&<div className="empty">Анкет пока нет</div>}</div></section>}
        {page==='invites'&&<section className="panel"><div className="panel-head"><div><h2>Приглашения</h2><p>Ссылки для заполнения анкеты</p></div><button className="primary-btn" onClick={()=>{setInviteForm({branchId:branches[0]?.id||'',daysValid:'30'});setModal('invite')}}><Plus size={16}/> Новая ссылка</button></div><div className="table-wrap"><table><thead><tr><th>ФИЛИАЛ</th><th>СОЗДАНА</th><th>СРОК</th><th>АНКЕТЫ</th><th>СТАТУС</th><th></th></tr></thead><tbody>{invites.map(i=><tr key={i.id}><td>{i.branch?.name}</td><td>{dateText(i.createdAt)}</td><td>{dateText(i.expiresAt)}</td><td>{i._count?.applications||0}</td><td>{i.active?'Активна':'Отключена'}</td><td><button className="icon-btn delete-icon" title="Удалить приглашение" disabled={busy} onClick={()=>removeRecord(`/invites/${i.id}`,`приглашение ${i.branch?.name||''}`)}><Trash2 size={16}/></button></td></tr>)}</tbody></table>{!invites.length&&<div className="empty">Приглашений пока нет</div>}</div></section>}
        {page==='reports'&&<section className="panel"><div className="panel-head"><div><h2>Отчёты сотрудников</h2><p>Проверяйте результаты выполнения поручений</p></div><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск по заданию или сотруднику..."/></div></div>{reports.filter(r=>`${r.task?.title||''} ${r.employee?.fullName||''} ${r.employee?.branch?.name||''}`.toLowerCase().includes(query.toLowerCase())).length?<div className="report-list">{reports.filter(r=>`${r.task?.title||''} ${r.employee?.fullName||''} ${r.employee?.branch?.name||''}`.toLowerCase().includes(query.toLowerCase())).map(r=><article className="report-card" key={r.id}><div className="panel-head"><div><h3>{r.task?.title||'Задание'}</h3><p>{r.employee?.fullName||'Сотрудник'} · {r.employee?.branch?.name||'Филиал не указан'} · {dateText(r.createdAt)}</p></div><span className={`pill ${r.status==='Принят'?'success':r.status==='На проверке'?'warning':'muted'}`}>{r.status}</span></div><div className="report-content"><b>Локация выполнения</b>{r.latitude!=null&&r.longitude!=null?<><p>{Number(r.latitude).toFixed(6)}, {Number(r.longitude).toFixed(6)}</p><div className="report-map-links"><a target="_blank" rel="noreferrer" href={`https://yandex.ru/maps/?pt=${r.longitude},${r.latitude}&z=16&l=map`}>Яндекс Карты</a><a target="_blank" rel="noreferrer" href={`https://www.google.com/maps?q=${r.latitude},${r.longitude}`}>Google Maps</a><a target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/?mlat=${r.latitude}&mlon=${r.longitude}#map=16/${r.latitude}/${r.longitude}`}>OpenStreetMap</a></div></>:<p>Геопозиция не указана</p>}<b>Фото и видео</b><div className="report-media-grid">{(r.media||[]).map((m,i)=>m.type?.startsWith('video/')?<video key={i} controls preload="metadata" src={m.data}/>:<a key={i} href={m.data} target="_blank" rel="noreferrer"><img src={m.data} alt={`Подтверждение ${i+1}`}/></a>)}</div>{r.adminComment&&<p className="report-comment">Комментарий руководителя: {r.adminComment}</p>}</div>{r.status==='На проверке'&&<div className="report-review"><label>Комментарий руководителя<textarea rows="2" value={reportComments[r.id]||''} onChange={e=>setReportComments(old=>({...old,[r.id]:e.target.value}))} placeholder="Обязателен при возврате на доработку"/></label><div className="inline-actions"><button className="secondary-btn" disabled={busy} onClick={()=>reviewReport(r,'Требует доработки')}>Вернуть на доработку</button><button className="primary-btn" disabled={busy} onClick={()=>reviewReport(r,'Принят')}>Принять отчёт</button></div></div>}</article>)}</div>:<div className="empty">Отчётов пока нет. Они появятся после отправки сотрудниками.</div>}</section>}
        {page==='location-requests'&&<section className="panel"><div className="panel-head"><div><h2>Запросы на посещение объектов</h2><p>Проверяйте выбранные сотрудниками локации</p></div></div><div className="table-wrap"><table className="location-requests-table"><thead><tr><th>СОТРУДНИК</th><th>ОБЪЕКТ</th><th>РЕГИОН / ГОРОД</th><th>ДАТА И ВРЕМЯ ДОБАВЛЕНИЯ</th><th>РЕШЕНИЕ</th><th></th></tr></thead><tbody>{locationSelections.map(x=><tr key={x.id}><td><b>{x.employee.fullName}</b><small className="subline">{x.employee.branch?.name||''}</small></td><td><b>{x.location.district||'Объект'}</b><small className="subline">{x.location.latitude.toFixed(5)}, {x.location.longitude.toFixed(5)}</small><button className="small-btn map-open-btn" onClick={()=>setMapSelection(x)}>Показать на карте</button></td><td>{x.location.region}<small className="subline">{x.location.city}</small></td><td><span className="location-created-at">{dateTimeText(x.createdAt)}</span></td><td><div className="inline-actions location-row-actions">{x.status==='На проверке'?<><button className="small-btn" onClick={()=>reviewLocation(x.id,'Одобрена')}>Одобрить</button><button className="small-btn danger-btn" onClick={()=>reviewLocation(x.id,'Отклонена')}>Отклонить</button></>:<span className={`pill ${x.status==='Одобрена'?'success':'muted'}`}>{x.status}</span>}<button className="icon-btn delete-icon" title="Удалить заявку" disabled={busy} onClick={()=>removeRecord(`/location-selections/${x.id}`,`заявку ${x.employee.fullName}`)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table>{!locationSelections.length&&<div className="empty">Запросов пока нет</div>}</div></section>}
        {page==='branches'&&<section className="panel"><div className="panel-head"><div><h2>Филиалы</h2><p>Подразделения предприятия</p></div><button className="primary-btn" onClick={()=>{setBranchName('');setBranchCity('');setModal('branch')}}><Plus size={16}/> Добавить филиал</button></div><div className="branch-grid">{branches.map(b=><div className="branch-card" key={b.id}><Building2/><b>{b.name}</b><small>{employees.filter(e=>e.branchId===b.id).length} сотрудников</small><label>Город филиала<input value={branchCityEdits[b.id]??b.city??''} onChange={e=>setBranchCityEdits(old=>({...old,[b.id]:e.target.value}))} placeholder="Например, Москва"/></label><button className="small-btn" disabled={busy||!(branchCityEdits[b.id]??b.city??'').trim()} onClick={()=>run(async()=>api(`/branches/${b.id}`,{method:'PATCH',body:JSON.stringify({city:branchCityEdits[b.id]??b.city})}))}>Сохранить город</button><button className="small-btn danger-btn" disabled={busy} onClick={()=>removeRecord(`/branches/${b.id}`,b.name)}><Trash2 size={14}/> Удалить филиал</button></div>)}</div>{!branches.length&&<div className="empty">Добавьте первый филиал</div>}</section>}
      </div>
      <footer>ПаркРайт <span>•</span> Версия 1.5.13 <span>•</span> Корпоративная система управления</footer>
    </main>
    {mapSelection&&(()=>{const loc=mapSelection.location;const lat=Number(loc.latitude);const lon=Number(loc.longitude);const coords=`${lat},${lon}`;const place=encodeURIComponent([loc.district,loc.city,loc.region].filter(Boolean).join(', '));return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setMapSelection(null)}}><div className="modal location-preview-modal"><div className="modal-head"><div><div className="map-modal-kicker">ЗАЯВКА СОТРУДНИКА</div><h2>Выбранный объект</h2><p>{mapSelection.employee.fullName} · {loc.city}, {loc.region}</p></div><button className="icon-btn" aria-label="Закрыть" onClick={()=>setMapSelection(null)}><X/></button></div><div id="admin-location-map" className="admin-location-map"/><div className="location-map-help"><span className="location-name">{loc.district||'Объект'}</span><span>{lat.toFixed(5)}, {lon.toFixed(5)}</span></div><div className="map-provider-section"><div><h3>Открыть в навигаторе</h3><p>Выберите удобный картографический сервис</p></div><div className="map-provider-grid"><a className="map-provider yandex" target="_blank" rel="noopener noreferrer" href={`https://yandex.ru/maps/?pt=${lon},${lat}&z=16&l=map&text=${place}`}><span className="provider-mark">Я</span><span><b>Яндекс Карты</b><small>Показать объект</small></span></a><a className="map-provider google" target="_blank" rel="noopener noreferrer" href={`https://www.google.com/maps/search/?api=1&query=${coords}`}><span className="provider-mark">G</span><span><b>Google Maps</b><small>Показать объект</small></span></a><a className="map-provider osm" target="_blank" rel="noopener noreferrer" href={`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=16/${lat}/${lon}`}><span className="provider-mark"><MapPin size={17}/></span><span><b>OpenStreetMap</b><small>Показать объект</small></span></a></div></div><div className="map-modal-footer"><span>Координаты объекта сотрудника</span><button className="secondary-btn" onClick={()=>setMapSelection(null)}>Закрыть</button></div></div></div>})()}
    {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal('')}}><div className="modal"><div className="modal-head"><div><h2>{{task:'Новое задание',invite:'Приглашение сотрудников',inviteResult:'Ссылка для анкеты',activationResult:'Активация личного кабинета',branch:'Новый филиал'}[modal]}</h2><p>Заполните необходимые поля</p></div><button className="icon-btn" onClick={()=>setModal('')}><X/></button></div>
      {modal==='task'&&<div className="form-grid"><label className="full">Сотрудник<select value={taskForm.employeeId} onChange={e=>setTaskForm({...taskForm,employeeId:e.target.value})}>{employees.filter(e=>e.status==='Работает').map(e=><option key={e.id} value={e.id}>{e.fullName} · {e.branch?.name}</option>)}</select></label><label className="full">Название задания<input required minLength={3} value={taskForm.title} onChange={e=>setTaskForm({...taskForm,title:e.target.value})} placeholder="Например, подготовить отчёт"/></label><label className="full">Описание и инструкции<textarea rows="4" value={taskForm.description} onChange={e=>setTaskForm({...taskForm,description:e.target.value})} placeholder="Опишите, что нужно сделать и какой результат ожидается"/></label><label className="full">Срок выполнения<input type="date" value={taskForm.dueDate} onChange={e=>setTaskForm({...taskForm,dueDate:e.target.value})}/></label></div>}
      {modal==='invite'&&<div className="form-grid"><div className="info-box full">Сотрудник откроет ссылку, заполнит анкету, а вы сможете проверить и принять её в разделе «Анкеты».</div><label className="full">Филиал<select value={inviteForm.branchId} onChange={e=>setInviteForm({...inviteForm,branchId:e.target.value})}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label className="full">Срок действия ссылки<select value={inviteForm.daysValid} onChange={e=>setInviteForm({...inviteForm,daysValid:e.target.value})}><option value="7">7 дней</option><option value="14">14 дней</option><option value="30">30 дней</option><option value="60">60 дней</option><option value="90">90 дней</option></select></label></div>}
      {modal==='activationResult'&&<div className="form-grid"><div className="info-box full">Анкета одобрена. Передайте сотруднику ссылку — он самостоятельно задаст логин и пароль. Ссылка действует 72 часа.</div><label className="full">Ссылка для активации<input readOnly value={inviteUrl}/></label><button className="secondary-btn full" onClick={()=>navigator.clipboard?.writeText(inviteUrl)}><Copy size={15}/> Скопировать ссылку</button></div>}
      {modal==='inviteResult'&&<div className="form-grid"><div className="info-box full">Отправьте ссылку сотруднику для заполнения анкеты.</div><label className="full">Ссылка для анкеты<input readOnly value={inviteUrl}/></label><button className="secondary-btn full" onClick={()=>navigator.clipboard?.writeText(inviteUrl)}><Copy size={15}/> Скопировать ссылку</button></div>}
      {modal==='branch'&&<div className="form-grid"><label className="full">Название филиала<input value={branchName} onChange={e=>setBranchName(e.target.value)} placeholder="Например, Филиал Москва"/></label><label className="full">Город филиала<input required value={branchCity} onChange={e=>setBranchCity(e.target.value)} placeholder="Например, Москва"/></label><div className="info-box full">Город используется для начального положения карты в личном кабинете сотрудников этого филиала.</div></div>}
      <div className="modal-actions"><button className="secondary-btn" onClick={()=>setModal('')}>Закрыть</button>{!['inviteResult','activationResult'].includes(modal)&&<button className="primary-btn" disabled={busy||(modal==='task'&&(!employees.some(e=>e.status==='Работает')||taskForm.title.trim().length<3))||(modal==='invite'&&!branches.length)} onClick={modal==='task'?createTask:modal==='invite'?createInvite:()=>run(async()=>api('/branches',{method:'POST',body:JSON.stringify({name:branchName,city:branchCity})}))}>{busy?'Сохранение...':modal==='invite'?'Создать ссылку':'Сохранить'}</button>}</div>
    </div></div>}
  </div>;
}
function TaskTable({tasks,onStatus,onDelete}){
 const [openChat,setOpenChat]=useState('');
 const selectedTask=tasks.find(t=>t.id===openChat);
 return <div className="task-table-section">
  <div className="table-wrap"><table><thead><tr><th>ЗАДАНИЕ / ЛОКАЦИЯ</th><th>ИСПОЛНИТЕЛЬ</th><th>АДМИНИСТРАТОР</th><th>СРОК</th><th>СТАТУС</th><th>ДЕЙСТВИЕ</th><th></th></tr></thead><tbody>{tasks.map(t=><tr key={t.id}><td><b>{t.title}</b>{t.location&&<small className="subline">{[t.location.district,t.location.city,t.location.region].filter(Boolean).join(', ')} · <a target="_blank" rel="noreferrer" href={`https://www.google.com/maps?q=${t.location.latitude},${t.location.longitude}`}>На карте</a></small>}{t.description&&<small className="subline">{t.description}</small>}</td><td>{t.employee?.fullName||'—'}<small className="subline">{t.employee?.branch?.name||''}</small></td><td>{t.adminUsername||'—'}</td><td>{dateText(t.dueDate)}</td><td><span className={`pill ${t.status==='Выполнено'?'success':['В работе','На проверке'].includes(t.status)?'warning':'muted'}`}>{t.status}</span></td><td>{['Выполнено','На проверке'].includes(t.status)?(t.status==='Выполнено'?'Готово':'Отчёт на проверке'):<select value={t.status} onChange={e=>onStatus(t,e.target.value)}><option value="Новое">Новое</option><option value="В работе">В работе</option><option value="Требует доработки">Требует доработки</option></select>}</td><td><div className="task-row-actions"><button className={`icon-btn chat-toggle ${openChat===t.id?'active':''}`} title="Открыть чат задания" onClick={()=>setOpenChat(openChat===t.id?'':t.id)}><MessageCircle size={16}/></button><button className="icon-btn delete-icon" title="Удалить задание" onClick={()=>onDelete?.(t)}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table></div>
  {selectedTask&&<div className="task-chat-standalone"><div className="task-chat-context"><div><span>ЧАТ ПО ЗАДАНИЮ</span><b>{selectedTask.title}</b><small>{selectedTask.employee?.fullName||'Сотрудник не указан'} · {selectedTask.employee?.branch?.name||'Филиал не указан'}</small></div><button type="button" onClick={()=>setOpenChat('')} aria-label="Закрыть чат">×</button></div><ChatPanel taskId={selectedTask.id} role="admin" compact/></div>}
 </div>
}

function ChatPanel({taskId,role,compact=false}){
 const [messages,setMessages]=useState([]),[text,setText]=useState(''),[loading,setLoading]=useState(true),[sending,setSending]=useState(false),[error,setError]=useState('');
 const bottomRef=useRef(null); const endpoint=role==='employee'?`/employee/tasks/${taskId}/messages`:`/tasks/${taskId}/messages`;
 const load=async()=>{try{const rows=await api(endpoint);setMessages(rows);setError('');}catch(e){setError(e.message);}finally{setLoading(false);}};
 useEffect(()=>{let alive=true;const refresh=async()=>{try{const rows=await api(endpoint);if(alive){setMessages(rows);setError('');}}catch(e){if(alive)setError(e.message);}finally{if(alive)setLoading(false);}};refresh();const timer=setInterval(refresh,5000);return()=>{alive=false;clearInterval(timer);};},[endpoint]);
 useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:'smooth',block:'end'});},[messages.length]);
 const send=async e=>{e.preventDefault();const body=text.trim();if(!body||sending)return;setSending(true);setError('');try{const created=await api(endpoint,{method:'POST',body:JSON.stringify({body})});setMessages(old=>[...old,created]);setText('');}catch(e){setError(e.message);}finally{setSending(false);}};
 return <section className={`task-chat ${compact?'task-chat-compact':''}`}>
  <div className="task-chat-head">
    <div className="task-chat-title">
      <span className="chat-icon"><MessageCircle size={18}/></span>
      <div><b>Обсуждение задания</b><small>Переписка сотрудника и руководителя</small></div>
    </div>
    <span className="chat-live-dot">Синхронизация включена</span>
  </div>
  <div className="task-chat-messages">
    {loading?<div className="chat-empty"><span className="chat-loading-mark"><MessageCircle size={22}/></span><b>Загружаем сообщения</b><span>Секунду, обновляем переписку</span></div>
    :messages.length?messages.map(m=><div key={m.id} className={`chat-message ${m.senderRole===role?'mine':'theirs'}`}>
      <div className="chat-message-meta"><b>{m.senderName}</b><time>{dateTimeText(m.createdAt)}</time></div>
      <p>{m.body}</p>
    </div>)
    :<div className="chat-empty"><span className="chat-empty-icon"><MessageCircle size={25}/></span><b>Пока здесь тихо</b><span>Начните диалог — напишите первое сообщение по заданию.</span></div>}
    <div ref={bottomRef}/>
  </div>
  {error&&<div className="chat-error">{error}</div>}
  <form className="task-chat-compose" onSubmit={send}>
    <textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Напишите сообщение…" rows="1" maxLength="4000" onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e);}}}/>
    <button type="submit" disabled={!text.trim()||sending} aria-label="Отправить сообщение" title="Отправить сообщение">{sending?<span className="chat-send-loading"/>:<Send size={18}/>}</button>
  </form>
  <div className="chat-compose-hint"><span>Enter</span> — отправить <i/> <span>Shift + Enter</span> — новая строка</div>
</section>
}

function EmployeeApplicationPage({token}) {
  const [invite,setInvite]=useState(null); const [form,setForm]=useState({fullName:'',phone:'',birthYear:'',telegramUsername:''});
  const [error,setError]=useState(''); const [done,setDone]=useState(false); const [busy,setBusy]=useState(false);
  useEffect(()=>{api(`/public/invites/${token}`).then(setInvite).catch(e=>setError(e.message));},[token]);
  const update=(key,value)=>setForm(old=>({...old,[key]:value}));
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{await api(`/public/invites/${token}/applications`,{method:'POST',body:JSON.stringify(form)});setDone(true);}catch(e){setError(e.message);}finally{setBusy(false);}};
  return <div className="application-shell"><div className="application-card"><div className="application-brand"><img className="application-logo" src="/parkwright-logo.png" alt="ПаркРайт"/></div>{done?<div className="application-success"><div className="success-icon"><CheckCircle2 size={30}/></div><h1>Анкета отправлена!</h1><p>Спасибо. Руководитель проверит ваши данные. Повторно отправлять анкету не нужно.</p></div>:error&&!invite?<div className="application-error"><h1>Не удалось открыть анкету</h1><p>{error}</p></div>:<><div className="application-heading"><span className="eyebrow">АНКЕТА СОТРУДНИКА</span><h1>Заполните свои данные</h1><p>Пожалуйста, укажите актуальную информацию. Поля с * обязательны.</p>{invite&&<div className="branch-chip"><Building2 size={15}/> Филиал: <b>{invite.branch}</b></div>}</div>{error&&<div className="alert">{error}</div>}<form onSubmit={submit} className="application-form"><label>Фамилия и имя *<input required minLength={3} value={form.fullName} onChange={e=>update('fullName',e.target.value)} placeholder="Иванов Иван"/></label><label>Номер телефона *<input required minLength={5} value={form.phone} onChange={e=>update('phone',e.target.value)} placeholder="+7 900 000-00-00"/></label><div className="form-grid"><label>Год рождения<input type="number" inputMode="numeric" min="1900" max={new Date().getFullYear()} step="1" value={form.birthYear} onChange={e=>update('birthYear',e.target.value)} placeholder="Например, 1995"/></label><label>Никнейм в Telegram<input value={form.telegramUsername} onChange={e=>update('telegramUsername',e.target.value)} placeholder="@username"/></label></div><label className="consent-row"><input type="checkbox" required/> <span>Подтверждаю достоверность данных и согласен(на) на их обработку руководством предприятия для оформления кадровой записи.</span></label><button className="primary-btn application-submit" disabled={busy||!invite}>{busy?'Отправка...':'Отправить анкету'}</button></form></>}</div><div className="application-footer">ПаркРайт · Анкета для сотрудников</div></div>;
}

function EmployeeActivationPage({token}) {
  const [login,setLogin]=useState(''); const [password,setPassword]=useState(''); const [confirm,setConfirm]=useState(''); const [error,setError]=useState(''); const [done,setDone]=useState(false); const [busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();setError('');if(password!==confirm){setError('Пароли не совпадают');return;}setBusy(true);try{await api(`/public/employee-activation/${token}`,{method:'POST',body:JSON.stringify({login,password})});setDone(true);}catch(err){setError(err.message);}finally{setBusy(false);}};
  return <div className="login-shell"><form className="login-card" onSubmit={submit}><div className="application-brand"><img className="application-logo" src="/parkwright-logo.png" alt="ПаркРайт"/></div>{done?<div className="application-success"><div className="success-icon"><CheckCircle2 size={30}/></div><h1>Аккаунт создан!</h1><p>Теперь войдите в личный кабинет со своим логином и паролем.</p><a className="primary-btn application-submit" href="/employee">Перейти ко входу</a></div>:<><div className="application-heading"><span className="eyebrow">ПОСЛЕ ОДОБРЕНИЯ АНКЕТЫ</span><h1>Создайте аккаунт</h1><p>Придумайте логин и пароль для личного кабинета. Их будете знать только вы.</p></div>{error&&<div className="alert">{error}</div>}<label>Логин<input required minLength={3} maxLength={40} pattern="[a-zA-Z0-9._-]+" autoComplete="username" value={login} onChange={e=>setLogin(e.target.value)} placeholder="Например, ivanov"/></label><label>Пароль<input type="password" required minLength={8} maxLength={128} autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Минимум 8 символов"/></label><label>Повторите пароль<input type="password" required minLength={8} maxLength={128} autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Повторите пароль"/></label><button className="primary-btn application-submit" disabled={busy}>{busy?'Создание аккаунта...':'Создать аккаунт'}</button></>}</form><div className="application-footer">ПаркРайт · Личный кабинет сотрудника</div></div>;
}

function EmployeeLoginPage({onLogin}) {
  const [login,setLogin]=useState(''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{await api('/employee-auth/login',{method:'POST',body:JSON.stringify({login,password})});onLogin();}catch(err){setError(err.message);}finally{setBusy(false);}};
  return <div className="login-shell"><form className="login-card" onSubmit={submit}><div className="application-brand"><img className="application-logo" src="/parkwright-logo.png" alt="ПаркРайт"/></div><div className="application-heading"><span className="eyebrow">ЛИЧНЫЙ КАБИНЕТ</span><h1>Вход для сотрудников</h1><p>Введите логин и пароль, которые вы создали при активации аккаунта.</p></div>{error&&<div className="alert">{error}</div>}<label>Логин<input autoComplete="username" required value={login} onChange={e=>setLogin(e.target.value)} placeholder="Ваш логин"/></label><label>Пароль<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Ваш пароль"/></label><button className="primary-btn application-submit" disabled={busy}>{busy?'Вход...':'Войти в кабинет'}</button><p className="employee-login-help">Не удаётся войти? Обратитесь к руководителю.</p></form><div className="application-footer">ПаркРайт · Личный кабинет сотрудника</div></div>;
}
function EmployeeCabinet({onLogout}) {
 const [profile,setProfile]=useState(null),[tasks,setTasks]=useState([]),[error,setError]=useState(''),[comments,setComments]=useState({}),[reportForms,setReportForms]=useState({}),[busyId,setBusyId]=useState('');
 const [locations,setLocations]=useState([]),[selections,setSelections]=useState([]),[selected,setSelected]=useState(null);
 const [workerPosition,setWorkerPosition]=useState(null),[geoStatus,setGeoStatus]=useState(''),[refreshing,setRefreshing]=useState(false);
 const load=async()=>{try{const [p,t,l,s]=await Promise.all([api('/employee/me'),api('/employee/tasks'),api('/employee/locations'),api('/employee/location-selections')]);setProfile(p);setTasks(t);setLocations(l);setSelections(s);return true;}catch(e){setError(e.message);return false;}};
 const refreshData=async()=>{setRefreshing(true);setError('');try{await load();}finally{setRefreshing(false);}};
 useEffect(()=>{load();const timer=setInterval(load,300000);return()=>clearInterval(timer);},[]);
 const locateWorker=()=>{if(!navigator.geolocation){setGeoStatus('Браузер не поддерживает определение местоположения.');return;}setGeoStatus('Определяем местоположение…');navigator.geolocation.getCurrentPosition(pos=>{setWorkerPosition({latitude:pos.coords.latitude,longitude:pos.coords.longitude});setGeoStatus('Ваше местоположение определено. Ближайшие объекты показаны первыми.');},err=>{setGeoStatus(err.code===1?'Доступ к геолокации запрещён. Разрешите его в настройках браузера.':'Не удалось определить местоположение. Проверьте GPS и подключение.');},{enableHighAccuracy:true,timeout:15000,maximumAge:60000});};
 const distanceKm=(a,b)=>{const rad=x=>x*Math.PI/180;const dLat=rad(b.latitude-a.latitude),dLon=rad(b.longitude-a.longitude);const q=Math.sin(dLat/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));};
 const nearestLocations=workerPosition?[...locations].map(loc=>({...loc,distanceKm:distanceKm(workerPosition,loc)})).sort((a,b)=>a.distanceKm-b.distanceKm).slice(0,50):locations;
 const branchCity=profile?.branchCity||profile?.branch||'';
 const cityLocations=branchCity?locations.filter(loc=>String(loc.city||'').trim().toLocaleLowerCase('ru-RU')===String(branchCity).trim().toLocaleLowerCase('ru-RU')):[];
 const branchCenter=cityLocations.length?{latitude:cityLocations.reduce((sum,loc)=>sum+loc.latitude,0)/cityLocations.length,longitude:cityLocations.reduce((sum,loc)=>sum+loc.longitude,0)/cityLocations.length}:null;
 useEffect(()=>{
  if(!window.L||!document.getElementById('employee-location-map'))return;
  const initialCenter=branchCenter?[branchCenter.latitude,branchCenter.longitude]:[55.75,37.62];
  const map=window.L.map('employee-location-map').setView(workerPosition?[workerPosition.latitude,workerPosition.longitude]:initialCenter,workerPosition?10:(branchCenter?11:4));
  window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);
  const group=window.L.featureGroup();
  nearestLocations.forEach(loc=>{
   const color=loc.availability==='Доступен'?'#7968e9':'#858d9d';
   const marker=window.L.circleMarker([loc.latitude,loc.longitude],{radius:5,color,fillColor:color,fillOpacity:.8,weight:1});
   marker.bindPopup(`<b>${safeMap(loc.city)}</b><br>${safeMap(loc.district)}<br>${safeMap(loc.region)}<br>${loc.availability}${Number.isFinite(loc.distanceKm)?`<br>Расстояние: ${loc.distanceKm.toFixed(1)} км`:''}`);
   marker.on('click',()=>setSelected(loc));marker.addTo(group);
  });
  group.addTo(map);
  if(workerPosition){const me=window.L.circleMarker([workerPosition.latitude,workerPosition.longitude],{radius:10,color:'#1687ff',fillColor:'#1687ff',fillOpacity:1,weight:3});me.bindPopup('Вы находитесь здесь').addTo(map);if(group.getLayers().length)map.fitBounds(window.L.featureGroup([me,group]).getBounds().pad(.12));}
  return()=>map.remove();
 },[locations,workerPosition,profile?.branchCity,profile?.branch]);
 const updateTask=async(task,status)=>{setBusyId(task.id);try{await api(`/employee/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({status,employeeComment:comments[task.id]??task.employeeComment??''})});await load();}catch(e){setError(e.message);}finally{setBusyId('');}};
 const submitTaskReport=async(task)=>{const form=reportForms[task.id]||{};setBusyId(task.id);setError('');try{if(!form.position)throw new Error('Сначала определите местоположение выполнения задания');if(!form.files?.length)throw new Error('Добавьте хотя бы одну фотографию или видео');const signed=await api(`/employee/tasks/${task.id}/reports/upload-urls`,{method:'POST',body:JSON.stringify({files:form.files.map(file=>({name:file.name,type:file.type,size:file.size}))})});const media=await Promise.all(signed.uploads.map(async(upload,index)=>{const response=await fetch(upload.url,{method:'PUT',headers:upload.headers,body:form.files[index]});if(!response.ok)throw new Error(`Не удалось загрузить файл «${upload.name}» в Backblaze (${response.status})`);return {key:upload.key,type:upload.type,name:upload.name,size:upload.size};}));await api(`/employee/tasks/${task.id}/reports`,{method:'POST',body:JSON.stringify({latitude:form.position.latitude,longitude:form.position.longitude,media})});setReportForms(old=>({...old,[task.id]:{}}));await load();}catch(e){setError(e.message);}finally{setBusyId('');}};
 const captureReportPosition=task=>{if(!navigator.geolocation){setError('Браузер не поддерживает геолокацию');return;}setError('');navigator.geolocation.getCurrentPosition(pos=>setReportForms(old=>({...old,[task.id]:{...old[task.id],position:{latitude:pos.coords.latitude,longitude:pos.coords.longitude}}})),err=>setError(err.code===1?'Разрешите доступ к геолокации в браузере':'Не удалось определить координаты. Попробуйте ещё раз.'),{enableHighAccuracy:true,timeout:20000,maximumAge:0});};
 const choose=async()=>{if(!selected)return;setBusyId('location');setError('');try{await api('/employee/location-selections',{method:'POST',body:JSON.stringify({locationId:selected.id})});setSelected(null);await load();}catch(e){setError(e.message);}finally{setBusyId('');}};
 const pending=selections.filter(x=>x.status==='На проверке'),approved=selections.filter(x=>x.status==='Одобрена'),rejected=selections.filter(x=>x.status==='Отклонена');
 if(!profile&&!error)return <div className="login-shell"><div className="login-loading">Загружаем личный кабинет...</div></div>;
 return <div className="employee-cabinet"><header className="employee-topbar"><div className="application-brand"><img className="application-logo" src="/parkwright-logo.png" alt="ПаркРайт"/></div><div className="employee-header-actions"><button className="secondary-btn refresh-btn" onClick={refreshData} disabled={refreshing}><RefreshCw size={16} className={refreshing?'spin':''}/>{refreshing?'Обновление...':'Обновить данные'}</button><button className="logout-btn" onClick={onLogout}>Выйти</button></div></header><main className="employee-content">{error&&<div className="alert">{error}</div>}{profile&&<>
 <div className="employee-welcome"><div><span className="eyebrow">ЛИЧНЫЙ КАБИНЕТ</span><h1>Здравствуйте, {profile.fullName.split(' ')[1]||profile.fullName}!</h1><p>Выберите объект на карте и отправьте его руководителю на согласование.</p></div><div className="employee-avatar">{profile.fullName.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}</div></div>
 <section className="panel"><div className="panel-head"><div><h2>Уведомления</h2><p>Решения руководителя по выбранным объектам</p></div></div>
 {pending.map(x=><div className="location-notice pending" key={x.id}><b>Запрос отправлен на проверку</b><span>{x.location.city}, {x.location.district||x.location.region}</span><small>Ожидайте решения руководителя.</small></div>)}
 {approved.map(x=><div className="location-notice approved" key={x.id}><b>Объект одобрен — задание создано</b><span>{x.location.city}, {x.location.district||x.location.region}</span><small>Новое задание уже доступно в разделе «Мои задания».</small></div>)}
 {rejected.map(x=><div className="location-notice rejected" key={x.id}><b>Выбор объекта отклонён</b><span>{x.location.city}, {x.location.district||x.location.region}</span><small>{x.adminComment||'Руководитель не согласовал посещение этого объекта.'}</small></div>)}
 {!selections.length&&<div className="empty">Вы ещё не выбирали объект.</div>}</section>
 <section className="panel"><div className="panel-head"><div><h2>Выбрать объект на карте</h2><p>Нажмите на точку, чтобы увидеть объект, затем отправьте запрос на проверку</p></div></div>
 <div className="inline-actions" style={{marginBottom:12}}><button className="primary-btn" onClick={locateWorker}>Определить моё местоположение</button>{workerPosition&&<span className="employee-footnote">Местоположение определено</span>}</div>{geoStatus&&<div className="location-map-help" role="status">{geoStatus}</div>}
 <div className="location-map-wrap"><div id="employee-location-map" className="employee-location-map"></div></div>
 <div className="location-map-help">{workerPosition?`Показаны ${nearestLocations.length} ближайших объектов из ${locations.length.toLocaleString('ru-RU')}. Синяя точка — вы; фиолетовые точки доступны, серые уже ожидают проверки или одобрены.`:`${locations.length.toLocaleString('ru-RU')} объектов из Excel · ${branchCity?`Карта открыта в городе филиала: ${branchCity}. `:'Город филиала не задан — используется общий обзор. '}Нажмите «Определить моё местоположение», чтобы найти ближайшие.`}</div>
 {selected&&<div className="selected-location"><div><b>{selected.city||'Объект'}{selected.district?`, ${selected.district}`:''}</b><small>{selected.region} · {selected.latitude.toFixed(5)}, {selected.longitude.toFixed(5)} · {selected.availability}</small></div><button className="primary-btn" disabled={busyId==='location'||selected.availability!=='Доступен'||pending.length>0||approved.length>0} onClick={choose}>{busyId==='location'?'Отправка...':'Отправить на проверку'}</button></div>}
 </section>
 <section className="employee-profile panel"><div className="panel-head"><div><h2>Мои данные</h2><p>Информация из кадровой карточки</p></div><span className="pill success">{profile.status}</span></div><div className="employee-details"><div><small>ФИО</small><b>{profile.fullName}</b></div><div><small>Должность</small><b>{profile.position||'Не указана'}</b></div><div><small>Филиал</small><b>{profile.branch||'—'}</b></div><div><small>Телефон</small><b>{profile.phone||'—'}</b></div><div><small>Год рождения</small><b>{profile.birthYear||'—'}</b></div><div><small>Telegram</small><b>{profile.telegramUsername?`@${profile.telegramUsername}`:'—'}</b></div><div><small>Дата трудоустройства</small><b>{dateText(profile.hireDate)}</b></div><div><small>Логин</small><b>{profile.login}</b></div></div></section>
 <section className="panel"><div className="panel-head"><div><h2>Мои задания</h2><p>Задания, назначенные руководителем по согласованным объектам</p></div></div>{tasks.length?<div className="employee-task-list">{tasks.map(t=><article className="employee-task panel" key={t.id}><div className="panel-head"><div><h2>{t.title}</h2></div><span className={`pill ${t.status==='Выполнено'?'success':['В работе','На проверке'].includes(t.status)?'warning':'muted'}`}>{t.status}</span></div>{t.location&&<div className="task-description"><b>Место выполнения:</b> {[t.location.district,t.location.city,t.location.region].filter(Boolean).join(', ')}<br/><a target="_blank" rel="noreferrer" href={`https://yandex.ru/maps/?pt=${t.location.longitude},${t.location.latitude}&z=16&l=map`}>Открыть объект на карте</a><br/><small>Ответственный администратор: {t.adminUsername||'—'}</small></div>}{t.description&&<p className="task-description">{t.description}</p>}{t.reports?.[0]&&<div className="employee-report-state"><b>Последний отчёт: {t.reports[0].status}</b>{t.reports[0].adminComment&&<p>Комментарий руководителя: {t.reports[0].adminComment}</p>}</div>}<ChatPanel taskId={t.id} role="employee"/>{t.status!=='Выполнено'&&t.reports?.[0]?.status!=='На проверке'?<><div className="task-report-form"><div className="report-location-capture"><b>1. Локация выполнения</b><button type="button" className="secondary-btn" disabled={busyId===t.id} onClick={()=>captureReportPosition(t)}><MapPin size={15}/> {reportForms[t.id]?.position?'Обновить координаты':'Определить моё местоположение'}</button>{reportForms[t.id]?.position&&<small>Координаты: {reportForms[t.id].position.latitude.toFixed(6)}, {reportForms[t.id].position.longitude.toFixed(6)}</small>}</div><label className="task-comment-label"><b>2. Фото и видео с локации</b><input type="file" accept="image/*,video/*" multiple onChange={e=>setReportForms(old=>({...old,[t.id]:{...old[t.id],files:Array.from(e.target.files||[])}}))}/><small>Количество и размер вложений не ограничены приложением. Доступны изображения и видео; фактические пределы зависят от браузера и инфраструктуры.</small>{reportForms[t.id]?.files?.length>0&&<small>Выбрано файлов: {reportForms[t.id].files.length}</small>}</label></div><div className="inline-actions"><button className="primary-btn" disabled={busyId===t.id||!reportForms[t.id]?.position||!reportForms[t.id]?.files?.length} onClick={()=>submitTaskReport(t)}>{busyId===t.id?'Отправка...':'Отправить отчёт'}</button></div></>:t.status==='Выполнено'?<p className="employee-footnote">Отчёт принят. Задание выполнено.</p>:<p className="employee-footnote">Отчёт отправлен руководителю. Ожидайте проверки.</p>}</article>)}</div>:<div className="empty">Дополнительных заданий пока нет.</div>}</section>
 </>}</main></div>;
}
function safeMap(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

function EmployeeAuthGate(){
  const [auth,setAuth]=useState('checking');
  useEffect(()=>{api('/employee-auth/me').then(()=>setAuth('yes')).catch(()=>setAuth('no'));},[]);
  const logout=async()=>{try{await api('/employee-auth/logout',{method:'POST'});}finally{setAuth('no');}};
  if(auth==='checking')return <div className="login-shell"><div className="login-loading">Проверка доступа...</div></div>;
  return auth==='yes'?<EmployeeCabinet onLogout={logout}/>:<EmployeeLoginPage onLogin={()=>setAuth('yes')}/>;
}

function Stat({icon:Icon,label,value,note,tone}){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={20}/></div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-note">{note}</div></div>}
function ShiftTable({shifts}){return <div className="table-wrap"><table><thead><tr><th>СОТРУДНИК</th><th>ТИП СМЕНЫ</th><th>ДАТА</th><th>ВРЕМЯ</th><th>НАЧИСЛЕНО</th></tr></thead><tbody>{shifts.map(s=><tr key={s.id}><td><b>{s.employee?.fullName||'—'}</b><small className="subline">{s.employee?.branch?.name||''}</small></td><td>{s.shiftType?.name||'—'}</td><td>{dateText(s.workDate)}</td><td>{s.startedAt&&s.endedAt?`${s.startedAt}–${s.endedAt}`:'Не указано'}</td><td className="amount">{money(s.amount)}</td></tr>)}</tbody></table></div>}

function LoginPage({onLogin}) {
  const [username,setUsername]=useState(''); const [password,setPassword]=useState('');
  const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{await api('/auth/login',{method:'POST',body:JSON.stringify({username,password})});onLogin();}catch(err){setError(err.message);}finally{setBusy(false);}};
  return <div className="login-shell"><form className="login-card" onSubmit={submit}><div className="application-brand"><img className="application-logo" src="/parkwright-logo.png" alt="ПаркРайт"/></div><div className="application-heading"><span className="eyebrow">ЗАЩИЩЁННЫЙ ДОСТУП</span><h1>Вход в систему</h1><p>Введите логин и пароль руководителя.</p></div>{error&&<div className="alert">{error}</div>}<label>Логин<input autoComplete="username" required value={username} onChange={e=>setUsername(e.target.value)} placeholder="Логин"/></label><label>Пароль<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Пароль"/></label><button className="primary-btn application-submit" disabled={busy}>{busy?'Вход...':'Войти'}</button></form><div className="application-footer">ПаркРайт · Доступ только для руководителя</div></div>;
}
function AuthGate(){
  const [auth,setAuth]=useState('checking');
  const check=()=>api('/auth/me').then(()=>setAuth('yes')).catch(()=>setAuth('no'));
  useEffect(()=>{check();},[]);
  const logout=async()=>{try{await api('/auth/logout',{method:'POST'});}finally{setAuth('no');}};
  if(auth==='checking') return <div className="login-shell"><div className="login-loading">Проверка доступа...</div></div>;
  return auth==='yes'?<App onLogout={logout}/>:<LoginPage onLogin={()=>setAuth('yes')}/>;
}
function Root(){ const path=window.location.pathname; return path.startsWith('/anketa/') ? <EmployeeApplicationPage token={path.split('/')[2]||''}/> : path.startsWith('/activate/') ? <EmployeeActivationPage token={path.split('/')[2]||''}/> : path.startsWith('/employee') ? <EmployeeAuthGate/> : <AuthGate/>; }

createRoot(document.getElementById('root')).render(<Root/>);
